namespace allmight {
void verify(bool ok, const char* explanation) {
    if (!ok) throw std::runtime_error(explanation); // checks survive NDEBUG
}

struct Asset {
    std::string name;                     // owns its characters
    std::vector<std::uint8_t> source;     // owns its bytes
};

// Keep identity independent of where a std::vector element happens to live.
// Reusing an old slot changes its generation, so stale handles are rejected.
struct AssetHandle {
    std::size_t slot;
    std::uint64_t generation;
    friend bool operator==(const AssetHandle&, const AssetHandle&) = default;
};

class AssetRegistry {
    struct Slot {
        std::optional<Asset> value;
        std::uint64_t generation = 1;
    };
    std::vector<Slot> slots_;
    std::vector<std::size_t> free_;
    std::unordered_map<std::string, AssetHandle> names_;

public:
    std::size_t slot_count() const noexcept { return slots_.size(); }
    std::size_t size() const noexcept { return names_.size(); }
    std::size_t capacity() const noexcept { return slots_.capacity(); }

    // Single-threaded transaction: a new slot is published to the name index
    // only after the owning Asset is complete. Roll back a slot if the hash
    // insertion throws; existing handles and values remain unchanged.
    AssetHandle insert(std::string name, std::vector<std::uint8_t> source,
                       bool fail_preparation = false, bool fail_commit = false) {
        if (name.empty() || source.empty())
            throw std::invalid_argument("asset name/data cannot be empty");
        if (names_.contains(name))
            throw std::invalid_argument("duplicate asset name");
        if (fail_preparation)
            throw std::runtime_error("simulated failure before publication");

        static_assert(std::is_nothrow_move_constructible_v<Asset>);
        // When a slot is reused, its already-incremented generation identifies
        // the NEW occupant, not the previous object once held at that index.
        const bool reuse = !free_.empty();
        const std::size_t index = reuse ? free_.back() : slots_.size();
        if (!reuse) slots_.emplace_back();
        Slot& slot = slots_[index];
        slot.value.emplace(Asset{std::move(name), std::move(source)});
        const AssetHandle handle{index, slot.generation};
        try {
            // Deliberately fail after constructing the slot but before its
            // name becomes externally discoverable, then verify rollback.
            if (fail_commit) throw std::runtime_error("injected commit failure");
            const auto [it, published] = names_.emplace(slot.value->name, handle);
            (void)it;
            if (!published) throw std::logic_error("duplicate during commit");
        } catch (...) {
            slot.value.reset(); // release the uncommitted owning payload
            if (!reuse) slots_.pop_back();
            throw;
        }
        if (reuse) free_.pop_back();
        return handle;
    }

    const Asset* resolve(AssetHandle h) const noexcept {
        if (h.slot >= slots_.size()) return nullptr;
        const Slot& slot = slots_[h.slot];
        if (slot.generation != h.generation || !slot.value) return nullptr;
        return std::addressof(*slot.value);
    }
    std::optional<AssetHandle> find(std::string_view name) const {
        // The temporary owns the queried characters during this lookup.
        // A production transparent hasher could avoid this allocation.
        auto it = names_.find(std::string(name));
        if (it == names_.end()) return std::nullopt;
        return it->second;
    }
    bool erase(AssetHandle h) {
        const Asset* found = resolve(h);
        if (!found) return false;
        if (slots_[h.slot].generation == std::numeric_limits<std::uint64_t>::max())
            throw std::overflow_error("generation exhausted; cannot reuse slot");
        // Reserving free-list capacity happens before mutations, so failure
        // here does not remove the published asset.
        free_.reserve(free_.size() + 1);
        names_.erase(found->name);
        Slot& slot = slots_[h.slot];
        slot.value.reset(); // destroys the stored name and byte vector
        ++slot.generation;
        free_.push_back(h.slot);
        return true;
    }
};

struct ConstantHash {
    std::size_t operator()(const std::string&) const noexcept { return 0; }
};

struct UploadJob { int priority; std::uint64_t sequence; std::string name; };
struct JobLess {
    bool operator()(const UploadJob& left, const UploadJob& right) const {
        if (left.priority != right.priority) return left.priority < right.priority;
        // Earlier sequence wins ties; priority_queue is not inherently stable.
        return left.sequence > right.sequence;
    }
};

std::size_t checksum(std::span<const std::uint8_t> bytes) noexcept {
    std::size_t sum = 0;
    for (std::uint8_t byte : bytes) sum += byte;
    return sum;
}

void run() {
    // vector: size means live elements, capacity means available storage.
    std::vector<int> dense;
    dense.reserve(2);
    verify(dense.size() == 0 && dense.capacity() >= 2, "reserve does not create elements");
    dense.push_back(10);
    dense.push_back(20);
    const std::size_t capacity_before = dense.capacity();
    // At this point a pointer/span into dense could be retained only if no
    // invalidating operation follows. We intentionally retain NO such pointer.
    dense.push_back(30); // guaranteed to reallocate when size == capacity
    const std::size_t capacity_after_growth = dense.capacity();
    verify(capacity_after_growth > capacity_before && dense.size() == 3,
           "growth requires new capacity; old iterators would be invalid");
    dense.resize(5); // constructs two live zero-initialized int elements
    verify(dense.size() == 5 && dense[3] == 0 && dense[4] == 0,
           "resize changes size, not merely reserved storage");
    std::cout << "vector capacity growth: " << capacity_before << " -> "
              << capacity_after_growth << "\n";

    // array stays fixed and contiguous. deque permits cheap front/back work,
    // but is not itself one contiguous T[N] allocation and has distinct rules.
    std::array<int, 3> fixed{2, 4, 6};
    verify(checksum(std::span<const std::uint8_t>{}) == 0, "empty span is valid");
    verify(fixed.size() == 3 && fixed.data()[2] == 6, "fixed array contiguous");
    std::deque<int> ends;
    ends.push_back(2);
    ends.push_front(1);
    ends.push_back(3);
    verify(ends.front() == 1 && ends.back() == 3 && ends[1] == 2,
           "deque indexed segmented sequence");

    // Linked containers keep node iterators/references stable under splicing,
    // subject to the operations' normal preconditions and erasure rules.
    std::list<std::string> edits{"import", "compile"};
    auto compile_it = std::next(edits.begin());
    std::list<std::string> incoming{"upload"};
    edits.splice(edits.end(), incoming, incoming.begin());
    verify(*compile_it == "compile" && incoming.empty() && edits.back() == "upload",
           "list node transfer preserves unrelated iterators");
    std::forward_list<int> singly{1, 2, 3};
    singly.erase_after(singly.begin()); // removes 2, not 1
    verify(std::vector<int>(singly.begin(), singly.end()) == std::vector<int>({1, 3}),
           "forward_list erase_after needs predecessor");

    // Ordered maps/sets use comparison order and logarithmic operations.
    std::map<std::string, int> named{{"mesh", 1}, {"shader", 3}, {"texture", 2}};
    std::set<int> unique_ids{8, 3, 8, 5};
    verify(named.begin()->first == "mesh" && unique_ids.size() == 3 &&
               *unique_ids.begin() == 3, "ordered unique-key containers");

    // Unordered containers are lookup-oriented. Hash equality MUST be
    // consistent with key equality. A pathological constant hash preserves
    // correctness, but forces the keys into one bucket.
    std::unordered_map<std::string, int, ConstantHash> collisions;
    collisions.max_load_factor(0.5f);
    for (int i = 0; i < 24; ++i) collisions.emplace("asset" + std::to_string(i), i);
    verify(collisions.size() == 24 && collisions.at("asset19") == 19,
           "collisions do not change key equality or lookup results");
    const auto bucket = collisions.bucket("asset0");
    verify(collisions.bucket_size(bucket) == collisions.size(),
           "constant hasher sends every key to one bucket");
    const auto buckets_before = collisions.bucket_count();
    collisions.reserve(96); // at max_load_factor 0.5, requests enough buckets
    verify(collisions.bucket_count() >= buckets_before &&
               collisions.load_factor() <= collisions.max_load_factor(),
           "rehash policy and load factor contract");
    // Do not dereference any pre-rehash iterator: rehash invalidates iterators.
    std::unordered_set<std::string> pending{"mesh", "texture", "mesh"};
    verify(pending.size() == 2 && pending.contains("texture"),
           "unordered_set expresses membership without a value field");

    // Adapters expose scheduling semantics, not iteration/layout guarantees.
    std::priority_queue<UploadJob, std::vector<UploadJob>, JobLess> priority;
    priority.push({3, 2, "later-high"});
    priority.push({1, 3, "low"});
    priority.push({3, 1, "earlier-high"});
    verify(priority.top().name == "earlier-high", "priority and tie break");
    priority.pop();
    verify(priority.top().name == "later-high", "heap next highest job");
    std::queue<int> arrivals;
    arrivals.push(7); arrivals.push(8);
    verify(arrivals.front() == 7, "queue FIFO"); arrivals.pop();
    verify(arrivals.front() == 8, "queue second arrival");
    std::stack<int> undo;
    undo.push(7); undo.push(8);
    verify(undo.top() == 8, "stack LIFO"); undo.pop();
    verify(undo.top() == 7, "stack previous entry");

    AssetRegistry registry;
    const AssetHandle first = registry.insert("rocks.mesh", {10, 20, 30});
    verify(registry.resolve(first) && registry.size() == 1,
           "asset is published at stable logical handle");
    verify(checksum(registry.resolve(first)->source) == 60,
           "span-like read over stored contiguous bytes");
    const auto found = registry.find("rocks.mesh");
    verify(found && *found == first, "owned name index returns logical handle");
    const std::size_t old_slots = registry.slot_count();
    bool failed = false;
    try { (void)registry.insert("broken.mesh", {1, 2, 3}, true); }
    catch (const std::runtime_error&) { failed = true; }
    verify(failed && registry.size() == 1 && registry.slot_count() == old_slots,
           "injected pre-publication error does not mutate registry");
    bool commit_failed = false;
    try { (void)registry.insert("commit-broken.mesh", {9, 9}, false, true); }
    catch (const std::runtime_error&) { commit_failed = true; }
    verify(commit_failed && registry.size() == 1 &&
               registry.slot_count() == old_slots && registry.resolve(first),
           "failed publication rolls back the unpublished slot");
    verify(registry.erase(first) && !registry.resolve(first),
           "old generation cannot resolve after erase");
    const AssetHandle second = registry.insert("fresh.mesh", {1, 2});
    verify(second.slot == first.slot && second.generation != first.generation &&
               !registry.resolve(first) && registry.resolve(second),
           "reused slot has a new generation and old handle remains stale");

    // string_view is a borrowed (pointer,length) view and may contain no NUL.
    // Copy to std::string when a name must survive the temporary source.
    std::string owner = "texture/stone/normal.png";
    std::string_view name_view{owner};
    const auto subpath = name_view.substr(8, 5); // "stone", not NUL terminated
    verify(subpath == "stone" && subpath.size() == 5, "view knows its length");
    const std::string owned_name{subpath};
    owner.clear(); // invalidates borrowed content; do not use subpath afterward
    verify(owned_name == "stone", "copied string survives source mutation");
    std::string short_text = "mesh";
    std::string long_text(1000, 'x');
    verify(short_text.size() == 4 && long_text.size() == 1000,
           "strings own content whether or not implementation uses SSO");
    std::cout << "string capacities (short/long): " << short_text.capacity()
              << '/' << long_text.capacity() << " (implementation-dependent)\n";
    std::cout << "asset_container_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_container_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Project AllMight M016 / Parts 251-270, C++20 executable reference.
// Extends the growing asset registry into a read-only query snapshot, typed
// results, ordered searches, deterministic reporting and safe erasure.
// No GPU submission, allocator benchmark or concurrent registry is claimed.
#include <algorithm>
#include <any>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <forward_list>
#include <functional>
#include <iostream>
#include <iterator>
#include <list>
#include <numeric>
#include <optional>
#include <ranges>
#include <sstream>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <type_traits>
#include <unordered_map>
#include <utility>
#include <variant>
#include <vector>

namespace allmight {

void check(bool condition, const char* failure) {
    if (!condition) throw std::runtime_error(failure); // active with -DNDEBUG
}

struct AssetHandle {
    std::uint32_t slot;
    std::uint64_t generation;
    friend bool operator==(AssetHandle, AssetHandle) = default;
};

enum class AssetKind { Mesh, Texture, Shader };
struct AssetRecord {
    AssetHandle id;
    std::string name; // owned; snapshots never borrow ephemeral file paths
    std::size_t bytes;
    int priority;
    AssetKind kind;
};

// A minimal snapshot of the earlier generation-checked registry. It is owned
// and detached from the live registry; handles in it may become stale later.
std::vector<AssetRecord> example_snapshot() {
    return {
        {{0, 1}, "brick.mesh", 48, 2, AssetKind::Mesh},
        {{1, 1}, "sky.tex", 64, 3, AssetKind::Texture},
        {{2, 1}, "ui.tex", 16, 3, AssetKind::Texture},
        {{3, 2}, "terrain.mesh", 128, 1, AssetKind::Mesh},
        {{4, 1}, "rock.mesh", 48, 2, AssetKind::Mesh},
    };
}

// Presence/absence answers a question with no meaningful failure reason.
std::optional<AssetHandle> find_optional(
    const std::vector<AssetRecord>& assets, std::string_view name) {
    const auto it = std::find_if(assets.begin(), assets.end(),
        [name](const AssetRecord& asset) { return asset.name == name; });
    if (it == assets.end()) return std::nullopt;
    return it->id; // value, not a reference into the snapshot
}

// Different error conditions need a typed result, not a magic sentinel ID.
enum class LookupError { EmptyName, NotFound };
template <class E> struct Unexpected { E error; };

template <class T, class E>
class ExpectedLike {
    std::variant<T, Unexpected<E>> state_;
    explicit ExpectedLike(T value) : state_(std::move(value)) {}
    explicit ExpectedLike(Unexpected<E> failed) : state_(failed) {}
public:
    static ExpectedLike success(T value) { return ExpectedLike(std::move(value)); }
    static ExpectedLike failure(E error) {
        return ExpectedLike(Unexpected<E>{error});
    }
    bool has_value() const noexcept { return std::holds_alternative<T>(state_); }
    const T& value() const { return std::get<T>(state_); }
    const E& error() const { return std::get<Unexpected<E>>(state_).error; }
};

ExpectedLike<AssetHandle, LookupError> lookup(
    const std::vector<AssetRecord>& assets, std::string_view name) {
    if (name.empty()) return ExpectedLike<AssetHandle, LookupError>::failure(
        LookupError::EmptyName);
    auto candidate = find_optional(assets, name);
    if (!candidate) return ExpectedLike<AssetHandle, LookupError>::failure(
        LookupError::NotFound);
    return ExpectedLike<AssetHandle, LookupError>::success(*candidate);
}

// A closed set of commands is expressed with std::variant and std::visit.
struct Inspect { AssetHandle id; };
struct Upload { AssetHandle id; };
struct Evict { AssetHandle id; };
using AssetCommand = std::variant<Inspect, Upload, Evict>;

template <class... Functions> struct Overloaded : Functions... {
    using Functions::operator()...;
};
template <class... Functions> Overloaded(Functions...) -> Overloaded<Functions...>;

// A comparator with both argument orders supports lower_bound, upper_bound
// and equal_range on a vector sorted by byte count. Their precondition is a
// properly partitioned/sorted range under the SAME ordering relation.
struct CompareBytes {
    bool operator()(const AssetRecord& asset, std::size_t n) const noexcept {
        return asset.bytes < n;
    }
    bool operator()(std::size_t n, const AssetRecord& asset) const noexcept {
        return n < asset.bytes;
    }
};

void run() {
    auto assets = example_snapshot();
    check(assets.size() == 5, "owned snapshot retains five assets");

    // 251: Optional means 'may be missing' but does not encode why.
    const auto present = find_optional(assets, "rock.mesh");
    const auto absent = find_optional(assets, "missing.tex");
    check(present && *present == AssetHandle{4, 1} && !absent,
          "optional presence/absence is explicit");

    // 254: C++20 expected-like result is a deliberately small teaching type.
    const auto good = lookup(assets, "rock.mesh");
    const auto blank = lookup(assets, "");
    const auto missing = lookup(assets, "other.mesh");
    check(good.has_value() && good.value() == AssetHandle{4, 1},
          "expected-like success carries an ID");
    check(!blank.has_value() && blank.error() == LookupError::EmptyName &&
          !missing.has_value() && missing.error() == LookupError::NotFound,
          "expected-like failure preserves error cause");

    // 252: A visitor must handle each of the closed command alternatives.
    std::vector<AssetCommand> commands{Inspect{{0, 1}}, Upload{{1, 1}}, Evict{{2, 1}}};
    std::size_t inspect_count = 0, upload_count = 0, evict_count = 0;
    for (const AssetCommand& command : commands) {
        std::visit(Overloaded{
            [&](const Inspect& op) { check(op.id.slot == 0, "inspect ID"); ++inspect_count; },
            [&](const Upload& op) { check(op.id.slot == 1, "upload ID"); ++upload_count; },
            [&](const Evict& op) { check(op.id.slot == 2, "evict ID"); ++evict_count; },
        }, command);
    }
    check(inspect_count == 1 && upload_count == 1 && evict_count == 1,
          "visit dispatches by active type rather than casted bytes");

    // 253: An open-ended diagnostics channel can accept std::any. Wrong-type
    // access throws; any_cast does not magically convert string to integer.
    std::any diagnostic = std::string("texture-rgba");
    check(std::any_cast<const std::string&>(diagnostic) == "texture-rgba",
          "any stores an owned concrete value");
    bool wrong_type = false;
    try { (void)std::any_cast<int>(diagnostic); }
    catch (const std::bad_any_cast&) { wrong_type = true; }
    check(wrong_type, "bad_any_cast is detectable");
    diagnostic.reset();
    check(!diagnostic.has_value(), "empty std::any owns no target");

    // 255-256: A pair is two values; a tuple allows an arbitrary fixed set of
    // heterogeneous fields. Structured bindings copy with 'auto', and bind
    // to the original pair members with 'auto&'.
    std::pair<std::size_t, std::size_t> counts{assets.size(), 0};
    auto [copied_count, copied_errors] = counts;
    auto& [live_count, live_errors] = counts;
    ++live_errors;
    check(copied_count == 5 && copied_errors == 0 &&
          live_count == 5 && counts.second == 1,
          "structured bindings distinguish copies from aliases");
    const auto report = std::tuple{std::string("frame-assets"), assets.size(), 1u};
    const auto& [report_name, report_count, report_version] = report;
    check(report_name == "frame-assets" && report_count == 5 && report_version == 1,
          "tuple exposes fixed typed fields");

    // 257-258: iterator categories are compile-time capabilities; a deque
    // has random-access iterators but NOT contiguous element storage.
    static_assert(std::contiguous_iterator<std::vector<int>::iterator>);
    static_assert(std::random_access_iterator<std::deque<int>::iterator>);
    static_assert(!std::contiguous_iterator<std::deque<int>::iterator>);
    static_assert(std::bidirectional_iterator<std::list<int>::iterator>);
    static_assert(!std::random_access_iterator<std::list<int>::iterator>);
    static_assert(std::forward_iterator<std::forward_list<int>::iterator>);
    static_assert(!std::bidirectional_iterator<std::forward_list<int>::iterator>);
    static_assert(std::input_iterator<std::istream_iterator<int>>);
    static_assert(!std::forward_iterator<std::istream_iterator<int>>);
    std::istringstream input{"7 8 9"};
    std::vector<int> parsed{std::istream_iterator<int>{input}, std::istream_iterator<int>{}};
    check(parsed == std::vector<int>({7, 8, 9}), "input iterator consumes stream once");

    // 260: Sorting is not required to preserve equal-key input order.
    auto sorted = assets; // own a separate snapshot before rearranging
    std::sort(sorted.begin(), sorted.end(), [](const AssetRecord& a, const AssetRecord& b) {
        if (a.bytes != b.bytes) return a.bytes < b.bytes;
        return a.name < b.name; // deterministic tie break, not relied on stability
    });
    check(sorted.front().name == "ui.tex" && sorted.back().name == "terrain.mesh",
          "sort orders by bytes with explicit tie break");

    // 261: Stable sort DOES preserve original order for equivalent priorities.
    auto stable = assets;
    std::stable_sort(stable.begin(), stable.end(), [](const AssetRecord& a, const AssetRecord& b) {
        return a.priority > b.priority;
    });
    check(stable[0].name == "sky.tex" && stable[1].name == "ui.tex" &&
          stable[2].name == "brick.mesh" && stable[3].name == "rock.mesh",
          "stable_sort preserves equal-priority relative order");

    // 262: Partition divides two groups but does not sort either group or
    // guarantee the original relative order inside the groups.
    auto partitioned = assets;
    const auto dividing = std::partition(partitioned.begin(), partitioned.end(),
        [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; });
    check(std::all_of(partitioned.begin(), dividing,
            [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }) &&
          std::none_of(dividing, partitioned.end(),
            [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }),
          "partition places predicate-true records first");
    check(std::partition_point(partitioned.begin(), partitioned.end(),
          [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }) == dividing,
          "partition_point requires already partitioned input");

    // 263-264: binary search requires the appropriate sorted/partitioned
    // order. Find both limits of the byte-size==48 subrange.
    std::sort(sorted.begin(), sorted.end(), [](const AssetRecord& a, const AssetRecord& b) {
        return a.bytes < b.bytes;
    });
    const auto lower = std::lower_bound(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    const auto upper = std::upper_bound(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    const auto both = std::equal_range(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    check(std::distance(sorted.begin(), lower) == 1 &&
          std::distance(sorted.begin(), upper) == 3 &&
          both.first == lower && both.second == upper,
          "binary-search contract finds exactly two 48-byte assets");
    check(std::lower_bound(sorted.begin(), sorted.end(), std::size_t{50}, CompareBytes{})
              == upper, "insertion point for nonmatching byte count");

    // 265: Linear find is appropriate for unsorted names when building a
    // one-off snapshot; the live registry from M015 has a separate hash index.
    std::vector<std::string> names;
    names.reserve(assets.size());
    std::transform(assets.begin(), assets.end(), std::back_inserter(names),
                   [](const AssetRecord& a) { return a.name; });
    check(std::find(names.begin(), names.end(), "sky.tex") != names.end() &&
          std::find(names.begin(), names.end(), "absent") == names.end(),
          "linear find works without sorted input");

    // 266: transform is an elementwise expression here, not a guarantee of
    // parallel execution or SIMD. Preserve a numeric snapshot for reduction.
    std::vector<std::size_t> byte_sizes;
    byte_sizes.reserve(assets.size());
    std::transform(assets.begin(), assets.end(), std::back_inserter(byte_sizes),
                   [](const AssetRecord& a) { return a.bytes; });
    check(byte_sizes == std::vector<std::size_t>({48, 64, 16, 128, 48}),
          "transform projects each asset size");

    // 267-268: accumulate is an ordered left fold; reduce may regroup.
    // Unsigned sums are exact for these small values. Floating point requires
    // an explicit numerical-accuracy/reproducibility policy.
    const auto sequential_sum = std::accumulate(byte_sizes.begin(), byte_sizes.end(),
                                                std::size_t{0});
    const auto regroupable_sum = std::reduce(byte_sizes.begin(), byte_sizes.end(),
                                             std::size_t{0});
    check(sequential_sum == 304 && regroupable_sum == 304,
          "both integer reductions compute a small exact byte total");
    const double large = 1e20;
    const double a = ((large + 1.0) - large) + 3.0;
    const double b = (large - large) + (1.0 + 3.0);
    check(a == 3.0 && b == 4.0,
          "floating-point regrouping can change a result");

    // 269: remove_if rearranges the logical retained prefix; vector::erase
    // must destroy the obsolete suffix and actually reduce the size.
    std::vector<int> work_ids{1, 2, 3, 4, 5, 6};
    const auto retained_end = std::remove_if(work_ids.begin(), work_ids.end(),
                                            [](int id) { return id % 2 == 0; });
    check(std::distance(work_ids.begin(), retained_end) == 3 &&
          work_ids.size() == 6, "remove_if does not shrink vector");
    work_ids.erase(retained_end, work_ids.end());
    check(work_ids == std::vector<int>({1, 3, 5}),
          "erase/remove destroys the removed logical suffix");

    // 270: std::erase_if (C++20) expresses the combined operation directly.
    auto texture_removed = assets;
    const auto removed = std::erase_if(texture_removed,
        [](const AssetRecord& a) { return a.kind == AssetKind::Texture; });
    check(removed == 2 && texture_removed.size() == 3 &&
          std::all_of(texture_removed.begin(), texture_removed.end(),
            [](const AssetRecord& a) { return a.kind != AssetKind::Texture; }),
          "erase_if reports count and shrinks container");
    std::unordered_map<std::string, int> diagnostics{{"sky.tex", 3}, {"brick.mesh", 2}};
    const auto hash_removed = std::erase_if(diagnostics,
        [](const auto& key_and_priority) { return key_and_priority.second == 3; });
    check(hash_removed == 1 && diagnostics.size() == 1 &&
          diagnostics.contains("brick.mesh"),
          "C++20 erase_if works on appropriate associative containers");

    std::cout << "asset_query_algorithm_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_query_algorithm_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// AllMight M017, Parts 271-280: owned snapshot queries, ranges, allocators, PMR.
// C++20; deterministic CPU model, NOT a graphics driver / concurrent registry.
#include <algorithm>
#include <array>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <iostream>
#include <iterator>
#include <limits>
#include <memory>
#include <memory_resource>
#include <numeric>
#include <ranges>
#include <span>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <unordered_map>
#include <utility>
#include <vector>

namespace allmight::asset_query {

void require(bool valid, const char* what) {
    if (!valid) throw std::runtime_error(what); // valid even with -DNDEBUG
}

// An owning snapshot is a separate lifetime from the live asset registry.
// Tombstones stay in this example to make a custom forward iterator useful.
struct Row {
    std::string name;
    std::size_t bytes;
    bool live;
};

std::vector<Row> make_snapshot() {
    return {{"brick.mesh", 48, true}, {"retired.tex", 512, false},
            {"sky.tex", 64, true}, {"ui.tex", 16, true},
            {"terrain.mesh", 128, true}, {"rock.mesh", 48, true}};
}

// Custom multi-pass forward iterator. It borrows the Row vector and skips
// tombstones, but does not own the vector or preserve validity on reallocation.
class LiveRowIterator {
    const std::vector<Row>* rows_ = nullptr;
    std::size_t pos_ = 0;

    void skip_dead() noexcept {
        if (!rows_) return;
        while (pos_ < rows_->size() && !(*rows_)[pos_].live) ++pos_;
    }
public:
    using iterator_concept = std::forward_iterator_tag;
    using iterator_category = std::forward_iterator_tag;
    using value_type = Row;
    using difference_type = std::ptrdiff_t;
    using reference = const Row&;

    LiveRowIterator() = default;
    LiveRowIterator(const std::vector<Row>& rows, std::size_t pos)
        : rows_(&rows), pos_(pos) { skip_dead(); }
    reference operator*() const noexcept { return (*rows_)[pos_]; }
    const Row* operator->() const noexcept { return std::addressof(**this); }
    LiveRowIterator& operator++() noexcept { ++pos_; skip_dead(); return *this; }
    LiveRowIterator operator++(int) noexcept { auto old = *this; ++*this; return old; }
    friend bool operator==(const LiveRowIterator&, const LiveRowIterator&) = default;
};
static_assert(std::forward_iterator<LiveRowIterator>);
static_assert(!std::bidirectional_iterator<LiveRowIterator>);
static_assert(!std::contiguous_iterator<LiveRowIterator>);

// begin() and end() are discovered in range-based for's exposition model.
// A range-for keeps its range expression alive for the loop, but a returned
// view or stored iterator still requires explicit owner-lifetime reasoning.
struct LiveRows {
    const std::vector<Row>* owner;
    LiveRowIterator begin() const { return LiveRowIterator{*owner, 0}; }
    LiveRowIterator end() const { return LiveRowIterator{*owner, owner->size()}; }
};
static_assert(std::ranges::forward_range<LiveRows>);

// An illustrative C++ allocator: typed allocate/deallocate must be paired.
// The shared statistics object survives copies/rebinds of the allocator.
struct AllocationStats {
    std::size_t allocations = 0;
    std::size_t deallocations = 0;
    std::size_t allocated_bytes = 0;
};
template<class T>
struct TrackingAllocator {
    using value_type = T;
    std::shared_ptr<AllocationStats> stats;
    TrackingAllocator() : stats(std::make_shared<AllocationStats>()) {}
    explicit TrackingAllocator(std::shared_ptr<AllocationStats> s) : stats(std::move(s)) {}
    template<class U>
    TrackingAllocator(const TrackingAllocator<U>& other) noexcept : stats(other.stats) {}
    T* allocate(std::size_t count) {
        if (count > std::allocator_traits<std::allocator<T>>::max_size(std::allocator<T>{}))
            throw std::bad_array_new_length();
        auto* raw = std::allocator<T>{}.allocate(count);
        ++stats->allocations;
        stats->allocated_bytes += count * sizeof(T);
        return raw;
    }
    void deallocate(T* ptr, std::size_t count) noexcept {
        ++stats->deallocations;
        std::allocator<T>{}.deallocate(ptr, count);
    }
    template<class U> friend struct TrackingAllocator;
    template<class U> bool operator==(const TrackingAllocator<U>& rhs) const noexcept {
        return stats == rhs.stats;
    }
};

// std::pmr moves the allocation-policy choice to runtime. The resource must
// outlive every container and object retaining a pointer to it.
class CountingMemoryResource final : public std::pmr::memory_resource {
    std::pmr::memory_resource* upstream_;
public:
    std::size_t allocated_blocks = 0;
    std::size_t freed_blocks = 0;
    std::size_t allocated_bytes = 0;
    explicit CountingMemoryResource(std::pmr::memory_resource* upstream)
        : upstream_(upstream) {}
private:
    void* do_allocate(std::size_t bytes, std::size_t alignment) override {
        void* ptr = upstream_->allocate(bytes, alignment);
        ++allocated_blocks;
        allocated_bytes += bytes;
        return ptr;
    }
    void do_deallocate(void* ptr, std::size_t bytes, std::size_t alignment) override {
        ++freed_blocks;
        upstream_->deallocate(ptr, bytes, alignment);
    }
    bool do_is_equal(const std::pmr::memory_resource& other) const noexcept override {
        return this == &other;
    }
};

// Function objects and lambdas give equivalent call semantics here, but
// code generation/allocations/capture size need MEASUREMENT, not slogans.
struct AtLeastBytes {
    std::size_t threshold;
    bool operator()(const Row& row) const noexcept { return row.bytes >= threshold; }
};

void run() {
    auto rows = make_snapshot();
    LiveRows live{&rows};
    std::size_t visits = 0;
    std::size_t total = 0;
    for (const Row& row : live) { // range-based for begin/end, not indexing
        ++visits;
        total += row.bytes;
    }
    require(visits == 5 && total == 304, "custom forward iterator skips tombstones");

    // Filter/transform adaptor creation is lazy. We can observe that neither
    // predicate nor transform runs until the range is iterated.
    std::size_t predicate_calls = 0;
    std::size_t projection_calls = 0;
    auto pipeline = std::views::all(rows)
        | std::views::filter([&](const Row& row) {
              ++predicate_calls;
              return row.live && row.bytes >= 48;
          })
        | std::views::transform([&](const Row& row) {
              ++projection_calls;
              return row.name;
          });
    require(predicate_calls == 0 && projection_calls == 0, "views compose lazily");
    std::vector<std::string> names;
    for (const auto& name : pipeline) names.push_back(name);
    require(names == std::vector<std::string>({"brick.mesh", "sky.tex",
                                               "terrain.mesh", "rock.mesh"}),
            "filter and transform produce the correct sequence");
    require(predicate_calls > 0 && projection_calls == 4,
            "predicates/transform execute during traversal");

    // Borrowed means iterators can outlive the range VIEW under its contract;
    // it does not mean the underlying vector's owner is kept alive.
    static_assert(std::ranges::borrowed_range<std::ranges::ref_view<std::vector<Row>>>);
    static_assert(!std::ranges::borrowed_range<std::vector<Row>>);
    static_assert(!std::ranges::borrowed_range<std::ranges::owning_view<std::vector<Row>>>);
    auto owned = std::views::all(make_snapshot()); // owns its vector in the view
    require(std::ranges::distance(owned) == 6, "rvalue vector becomes owning view");

    // A projection is supplied separately from a comparator: ranges::find
    // compares row.name, not the Row object or an allocated name list.
    auto located = std::ranges::find(rows, std::string_view{"sky.tex"}, &Row::name);
    require(located != rows.end() && located->bytes == 64,
            "projected ranges::find locates the named asset");
    auto sorted = rows;
    std::ranges::sort(sorted, std::less<>{}, &Row::bytes);
    require(sorted.front().bytes == 16 && sorted.back().bytes == 512,
            "projected ranges::sort uses byte count");

    AtLeastBytes functor{48};
    auto equivalent_lambda = [threshold = std::size_t{48}](const Row& row) noexcept {
        return row.bytes >= threshold;
    };
    require(std::ranges::count_if(rows, functor) ==
            std::ranges::count_if(rows, equivalent_lambda),
            "functor and captured lambda express same predicate");

    auto stats = std::make_shared<AllocationStats>();
    {
        std::vector<std::size_t, TrackingAllocator<std::size_t>> tracked{
            TrackingAllocator<std::size_t>{stats}};
        tracked.reserve(5);
        for (const Row& row : live) tracked.push_back(row.bytes);
        require(std::accumulate(tracked.begin(), tracked.end(), std::size_t{0}) == 304,
                "custom allocator does not change vector's value semantics");
        require(stats->allocations > 0 && stats->allocated_bytes >= 5*sizeof(std::size_t),
                "custom allocator observes requests");
    }
    require(stats->allocations == stats->deallocations,
            "typed allocator allocations paired by vector lifetime");

    CountingMemoryResource resource{std::pmr::new_delete_resource()};
    {
        std::pmr::vector<std::size_t> sizes{&resource};
        sizes.reserve(5);
        for (const Row& row : live) sizes.push_back(row.bytes);
        std::pmr::unordered_map<std::pmr::string, std::size_t> index{&resource};
        for (const Row& row : live)
            index.emplace(std::pmr::string{row.name, &resource}, row.bytes);
        require(index.size() == 5 && index.at(std::pmr::string{"sky.tex", &resource}) == 64,
                "pmr unordered_map uses resource for nodes/buckets");
        require(std::accumulate(sizes.begin(), sizes.end(), std::size_t{0}) == 304,
                "pmr vector and custom allocator produce same data result");
        require(resource.allocated_blocks > 0, "pmr resource intercepts allocation");
    }
    require(resource.allocated_blocks == resource.freed_blocks,
            "ordinary upstream resource releases deallocated blocks");

    CountingMemoryResource arena_upstream{std::pmr::new_delete_resource()};
    alignas(std::max_align_t) std::array<std::byte, 128> scratch{};
    {
        std::pmr::monotonic_buffer_resource arena{scratch.data(), scratch.size(),
                                                   &arena_upstream};
        {
            std::pmr::vector<std::uint64_t> pixels{&arena};
            pixels.resize(2048, 7); // exceeds scratch, must ask upstream
            require(pixels.size() == 2048 && pixels[2000] == 7,
                    "monotonic arena supplies live vector storage");
            require(arena_upstream.allocated_blocks > 0,
                    "exhausting stack scratch delegates upstream");
        }
        // pixels' destructor can call deallocate, but monotonic arena does
        // not return its blocks individually; release happens in bulk.
        require(arena_upstream.freed_blocks == 0,
                "monotonic deallocation doesn't return upstream blocks now");
    }
    require(arena_upstream.allocated_blocks == arena_upstream.freed_blocks,
            "arena destruction returns its upstream allocations");

    alignas(std::max_align_t) std::array<std::byte, 64> fixed_scratch{};
    std::pmr::monotonic_buffer_resource bounded{fixed_scratch.data(),
                                                fixed_scratch.size(),
                                                std::pmr::null_memory_resource()};
    bool exhausted = false;
    try {
        std::pmr::vector<std::uint64_t> huge{&bounded};
        huge.resize(2048, 2);
    } catch (const std::bad_alloc&) { exhausted = true; }
    require(exhausted, "fixed arena plus null upstream detects capacity exhaustion");
    std::cout << "asset_ranges_pmr_lab: all checks passed\n";
}
} // namespace allmight::asset_query

int main() {
    try { allmight::asset_query::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_ranges_pmr_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// TEST HARNESS: never silently discard semantic checks in -DNDEBUG builds.
// This must precede <cassert>; all original assertions remain active under -O2.
#if defined(NDEBUG)
#undef NDEBUG
#endif

// Phase 1 of AllMight: one engine request, two forms of runtime choice.
// Build with C++20, warnings-as-errors, and ASan/UBSan when available.
#include <cassert>
#include <compare>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <memory>
#include <stdexcept>
#include <string_view>
#include <variant>
#include <type_traits>

// A request is one of three known shapes. std::variant stores the active tag
// and constructs/destructs exactly the active alternative.
struct Clear { float red, green, blue; };
struct DrawMesh { std::uint32_t mesh_id, material_id; };
struct Upload { std::uint64_t byte_count; };
using Request = std::variant<Clear, DrawMesh, Upload>;

struct Counts { int clears=0, draws=0, uploads=0; std::uint64_t bytes=0; };

// An interface means the caller knows what a backend promises, not which
// implementation the application selected at runtime.
class Backend {
public:
    virtual ~Backend() = default; // critical for deleting via Backend*
    virtual void submit(const Request& request) = 0;
    virtual std::string_view name() const noexcept = 0;
};

class CountingBackend final : public Backend {
public:
    CountingBackend(Counts& counts, int& destroyed)
        : counts_(counts), destroyed_(destroyed) {}
    ~CountingBackend() override { ++destroyed_; }

    void submit(const Request& request) override {
        std::visit([this](const auto& operation) {
            using T = std::decay_t<decltype(operation)>;
            if constexpr (std::is_same_v<T, Clear>) {
                ++counts_.clears;
            } else if constexpr (std::is_same_v<T, DrawMesh>) {
                ++counts_.draws;
            } else {
                static_assert(std::is_same_v<T, Upload>);
                ++counts_.uploads;
                counts_.bytes += operation.byte_count;
            }
        }, request);
    }

    std::string_view name() const noexcept override { return "counting"; }
private:
    Counts& counts_; // borrowed: the caller keeps this alive during backend use
    int& destroyed_; // borrowed: test observes the derived destructor
};

class NullBackend final : public Backend {
public:
    void submit(const Request&) override {}
    std::string_view name() const noexcept override { return "null"; }
};

// An asset identity compares by both slot and generation. The compiler can
// synthesize equality and a strong (total) ordering for these integer fields.
struct AssetId {
    std::uint32_t slot;
    std::uint32_t generation;
    auto operator<=>(const AssetId&) const = default;
};

// Nontrivial inherited state can be sliced by copying only its base subobject.
struct NamedObject {
    std::string_view label{"base"};
    virtual ~NamedObject() = default;
    virtual std::string_view kind() const noexcept { return "base"; }
};
struct MeshObject : NamedObject {
    MeshObject() { label = "mesh"; }
    std::string_view kind() const noexcept override { return "mesh"; }
};

// Virtual inheritance creates one shared Root subobject even with two routes.
struct Root { int identifier = 42; };
struct Left : virtual Root {};
struct Right : virtual Root {};
struct Diamond : Left, Right {};

// Default arguments bind using the static type at the call site, whereas
// the selected virtual-function body depends on the dynamic type.
struct DispatchBase {
    virtual ~DispatchBase() = default;
    virtual int reserve(int n = 2) const { return n; }
};
struct DispatchDerived : DispatchBase {
    int reserve(int n = 7) const override { return n * 10; }
};

// Overload resolution selects a viable function before execution. These
// overloads expose the actual static type decision to the test.
constexpr int classify(int) { return 1; }
constexpr int classify(double) { return 2; }

int main() {
    Counts counts;
    int derived_destructor_calls = 0;
    {
        std::unique_ptr<Backend> backend =
            std::make_unique<CountingBackend>(counts, derived_destructor_calls);
        assert(backend->name() == "counting");
        backend->submit(Request{Clear{0.1f, 0.2f, 0.3f}});
        backend->submit(Request{DrawMesh{17u, 4u}});
        backend->submit(Request{Upload{4096u}});
        assert(counts.clears == 1 && counts.draws == 1);
        assert(counts.uploads == 1 && counts.bytes == 4096);

        // dynamic_cast tests dynamic type: null would mean another backend.
        auto* concrete = dynamic_cast<CountingBackend*>(backend.get());
        assert(concrete != nullptr);
        assert(dynamic_cast<NullBackend*>(backend.get()) == nullptr);
    }
    assert(derived_destructor_calls == 1); // virtual deletion reached the derived owner

    Request request = DrawMesh{8u, 2u};
    assert(std::holds_alternative<DrawMesh>(request));
    assert(std::get_if<Upload>(&request) == nullptr);
    request = Upload{128u};
    assert(std::get<Upload>(request).byte_count == 128u);

    const AssetId original{7u, 3u};
    assert((original == AssetId{7u, 3u}));
    assert((original != AssetId{7u, 4u}));
    assert((original <=> AssetId{8u, 1u}) < 0);
    // Floating-point order differs: NaN is *unordered*, not less/equal/greater.
    const double nan = std::numeric_limits<double>::quiet_NaN();
    assert((nan <=> 1.0) == std::partial_ordering::unordered);

    MeshObject mesh;
    NamedObject& borrowed = mesh;
    assert(borrowed.kind() == "mesh"); // virtual call reaches derived override
    NamedObject sliced = mesh;          // makes a *new base object*, losing derived type
    assert(sliced.kind() == "base");

    Diamond diamond;
    Root* via_left = static_cast<Root*>(static_cast<Left*>(&diamond));
    Root* via_right = static_cast<Root*>(static_cast<Right*>(&diamond));
    assert(via_left == via_right && via_left->identifier == 42);

    DispatchDerived derived;
    DispatchBase& base = derived;
    assert(base.reserve() == 20); // base's default 2; derived's body multiplies by 10
    assert(derived.reserve() == 70); // derived's default 7
    assert(classify(3) == 1 && classify(3.0) == 2);

    // A raw union can reuse storage for trivial members, but it provides no
    // automatic active-tag query. Do not read index after writing weight.
    union TrivialCell { std::uint32_t index; float weight; };
    TrivialCell cell{.index=5u};
    assert(cell.index == 5u);
    cell.weight = 0.5f;
    assert(cell.weight == 0.5f);

    std::cout << "backend_choice_lab: all semantic checks passed\n";
}

// Project AllMight, Phase 4 / M014 (Parts 217-230).
// One asset-tile planning problem exposes compile-time evaluation, policy choice,
// static dispatch, and object-layout consequences. This is a CPU-only witness.
#include <array>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <iostream>
#include <limits>
#include <span>
#include <stdexcept>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

namespace allmight {

void require(bool condition, const char* message) {
    if (!condition) throw std::runtime_error(message); // survives -DNDEBUG
}

enum class PixelFormat { R8, RGB8, RGBA8 };

// A type trait represents compile-time information as a type with a value.
// Each specialization defines only the supported format's channel count.
template <PixelFormat Format> struct PixelTraits;
template <> struct PixelTraits<PixelFormat::R8>
    : std::integral_constant<std::size_t, 1> {};
template <> struct PixelTraits<PixelFormat::RGB8>
    : std::integral_constant<std::size_t, 3> {};
template <> struct PixelTraits<PixelFormat::RGBA8>
    : std::integral_constant<std::size_t, 4> {};
static_assert(PixelTraits<PixelFormat::RGB8>::value == 3);
static_assert(std::is_base_of_v<std::integral_constant<std::size_t, 4>,
                                PixelTraits<PixelFormat::RGBA8>>);

struct TileDefinition { std::size_t width, height; };

// Immediate functions require compile-time evaluation for these calls.
// An invalid compile-time configuration must fail during compilation.
consteval TileDefinition make_tile_definition(std::size_t width,
                                               std::size_t height) {
    if (width == 0 || height == 0 || width > 64 || height > 64)
        throw "tile dimensions must be in [1, 64]";
    return {width, height};
}
inline constexpr TileDefinition kDefaultTile = make_tile_definition(8, 8);
static_assert(kDefaultTile.width * kDefaultTile.height == 64);

// A constexpr function can execute during constant evaluation OR at runtime.
// Its preconditions are checked in both cases. No unguarded multiplication.
constexpr std::size_t checked_product(std::size_t x, std::size_t y) {
    if (y != 0 && x > std::numeric_limits<std::size_t>::max() / y)
        throw std::overflow_error("byte-count multiplication overflow");
    return x * y;
}
static_assert(checked_product(8, 4) == 32);

// A 4-bit coordinate is spread into the even bit positions of one byte:
// abcd -> 0a0b0c0d. Two spread coordinates can be interleaved into a
// Morton/Z-order tile code, useful for addressing small 2D tile blocks.
constexpr std::uint8_t spread4(std::uint8_t n) noexcept {
    std::uint8_t result = 0;
    for (unsigned bit = 0; bit != 4; ++bit)
        result |= static_cast<std::uint8_t>(((n >> bit) & 1u) << (2u * bit));
    return result;
}

consteval std::array<std::uint8_t, 16> make_morton_table() {
    std::array<std::uint8_t, 16> result{};
    for (std::size_t n = 0; n < result.size(); ++n)
        result[n] = spread4(static_cast<std::uint8_t>(n));
    return result;
}
inline constexpr auto kSpread4 = make_morton_table();
static_assert(kSpread4[3] == 5 && kSpread4[5] == 17);

constexpr std::uint8_t morton4(std::uint8_t x, std::uint8_t y) {
    if (x >= 16 || y >= 16) throw std::out_of_range("4-bit Morton coordinate");
    return static_cast<std::uint8_t>(kSpread4[x] | (kSpread4[y] << 1));
}
static_assert(morton4(3, 5) == 39);

// constinit promises initialization at static initialization time, not constness
// and not thread safety. This demonstrator is used on a single thread only.
constinit std::uint32_t g_plans_recorded = 0;

// A stateless policy means no application-specific budget, not unchecked math.
// All paths still validate overflow, payload length and format constraints.
struct NoBudgetPolicy {
    void validate(std::size_t) const noexcept {}
};
struct ByteBudgetPolicy {
    std::size_t maximum;
    void validate(std::size_t count) const {
        if (count > maximum) throw std::length_error("tile exceeds byte budget");
    }
};
static_assert(std::is_empty_v<NoBudgetPolicy>);
static_assert(!std::is_empty_v<ByteBudgetPolicy>);

struct TilePlan {
    std::size_t width, height, bytes;
    std::uint8_t example_morton;
    bool alpha;
};

// The CRTP base calls a derived implementation at compile-time-known type.
// It is not a virtual interface and does not provide runtime extensibility.
template <class Derived> struct RecorderBase {
    void record(const TilePlan& plan) {
        static_cast<Derived&>(*this).record_impl(plan);
    }
};
struct CountingRecorder : RecorderBase<CountingRecorder> {
    std::size_t calls = 0, total_bytes = 0;
    void record_impl(const TilePlan& plan) {
        ++calls;
        total_bytes += plan.bytes;
    }
};

// Tags select distinct operations at compile time using ordinary overloads.
struct VerifyPayloadTag {};
struct MetadataOnlyTag {};
void check_payload(std::span<const std::byte> pixels,
                   std::size_t expected, VerifyPayloadTag) {
    if (pixels.size() != expected)
        throw std::invalid_argument("pixel data length does not match plan");
}
void check_payload(std::span<const std::byte>,
                   std::size_t, MetadataOnlyTag) noexcept {
    // This mode produces only a manifest and never asserts buffer readiness.
}

// Template policies are selected at compile time. A no_unique_address member
// allows an empty NoBudgetPolicy to overlap other storage where permitted.
template <PixelFormat Format, class BudgetPolicy, class Recorder>
class TilePlanner {
    [[no_unique_address]] BudgetPolicy budget_;
    Recorder recorder_;
public:
    TilePlanner(BudgetPolicy budget, Recorder recorder)
        : budget_(std::move(budget)), recorder_(std::move(recorder)) {}

    template <class Tag>
    TilePlan prepare(std::size_t width, std::size_t height,
                     std::span<const std::byte> payload, Tag tag) {
        if (width == 0 || height == 0)
            throw std::invalid_argument("tile dimensions cannot be zero");
        const std::size_t pixels = checked_product(width, height);
        const std::size_t bytes =
            checked_product(pixels, PixelTraits<Format>::value);
        budget_.validate(bytes);
        check_payload(payload, bytes, tag);

        // This branch is discarded during instantiation for non-alpha formats.
        // It is an actual compile-time format decision, not a runtime if.
        bool alpha = false;
        if constexpr (Format == PixelFormat::RGBA8) {
            alpha = true;
        }
        TilePlan plan{width, height, bytes, morton4(3, 5), alpha};
        recorder_.record(plan); // static CRTP call into the concrete recorder
        ++g_plans_recorded;
        return plan;
    }

    const Recorder& recorder() const noexcept { return recorder_; }
};

// Classic empty-base optimization (EBO), contrasted with regular and
// C++20 potentially-overlapping members. Sizes are observed, not mandated.
struct PlainPolicyHolder { NoBudgetPolicy policy; std::size_t counter; };
struct EboPolicyHolder : private NoBudgetPolicy { std::size_t counter; };
struct CompactPolicyHolder {
    [[no_unique_address]] NoBudgetPolicy policy;
    std::size_t counter;
};

void run() {
    require(kDefaultTile.width == 8, "consteval configuration");
    require(morton4(3, 5) == 39, "Morton table and composition");
    require(checked_product(7, 6) == 42, "constexpr function at runtime");
    const std::size_t value = 13;
    require(checked_product(value, 3) == 39, "runtime constexpr call");

    using RgbaPlanner = TilePlanner<PixelFormat::RGBA8,
                                    ByteBudgetPolicy, CountingRecorder>;
    RgbaPlanner limited{ByteBudgetPolicy{64}, CountingRecorder{}};
    std::vector<std::byte> rgba(8 * 2 * 4, std::byte{0x7f});
    TilePlan accepted = limited.prepare(8, 2, rgba, VerifyPayloadTag{});
    require(accepted.bytes == 64 && accepted.alpha,
            "RGBA tile validated and recorded");
    require(limited.recorder().calls == 1 &&
            limited.recorder().total_bytes == 64, "static CRTP recorder");

    bool too_large = false;
    try {
        (void)limited.prepare(8, 3, {}, MetadataOnlyTag{}); // 96 > 64
    } catch (const std::length_error&) { too_large = true; }
    require(too_large && limited.recorder().calls == 1,
            "budget failure must not publish a plan");

    bool wrong_payload = false;
    try {
        (void)limited.prepare(4, 4, {}, VerifyPayloadTag{}); // 64 required
    } catch (const std::invalid_argument&) { wrong_payload = true; }
    require(wrong_payload && limited.recorder().calls == 1,
            "payload failure leaves recorder unchanged");

    TilePlanner<PixelFormat::RGB8, NoBudgetPolicy, CountingRecorder>
        manifest{NoBudgetPolicy{}, CountingRecorder{}};
    auto metadata = manifest.prepare(4, 4, {}, MetadataOnlyTag{});
    require(metadata.bytes == 48 && !metadata.alpha,
            "manifest is a plan only, not a verified upload");
    require(manifest.recorder().calls == 1,
            "second static policy and recorder instance");

    bool overflow = false;
    try {
        (void)manifest.prepare(std::numeric_limits<std::size_t>::max(),
                               2, {}, MetadataOnlyTag{});
    } catch (const std::overflow_error&) { overflow = true; }
    require(overflow && manifest.recorder().calls == 1,
            "overflow checked before byte multiplication");

    // Runtime type erasure has a different tradeoff from the statically
    // selected CRTP Recorder. It can hold a runtime-selected callable target.
    std::size_t observed = 0;
    std::function<void(const TilePlan&)> erased =
        [&observed](const TilePlan& plan) { observed += plan.bytes; };
    erased(metadata);
    require(observed == 48, "type-erased runtime callable");
    erased = {}; // release its captured target

    require(g_plans_recorded == 2, "constinit counter updated by accepted plans");
    require(sizeof(PlainPolicyHolder) >= sizeof(std::size_t),
            "ordinary member layout observed");
    require(sizeof(EboPolicyHolder) >= sizeof(std::size_t),
            "EBO layout observed");
    require(sizeof(CompactPolicyHolder) >= sizeof(std::size_t),
            "no_unique_address layout observed");
    std::cout << "Layout bytes (plain/EBO/member): "
              << sizeof(PlainPolicyHolder) << '/' << sizeof(EboPolicyHolder)
              << '/' << sizeof(CompactPolicyHolder) << '\n';
    std::cout << "compile_time_asset_policy_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& e) {
        std::cerr << "compile_time_asset_policy_lab failed: " << e.what() << '\n';
        return 1;
    }
}

// Standalone C++20 contact cache policy witness; no dependency on Kairo runtime.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror contact_cache_lab.cpp -o /tmp/contact_cache && /tmp/contact_cache
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <limits>
#include <map>
#include <stdexcept>
#include <vector>

struct Vec2 { double x{}, y{}; };
constexpr Vec2 operator*(Vec2 a, double s) { return {a.x*s, a.y*s}; }
constexpr double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }
constexpr Vec2 tangent(Vec2 n) { return {-n.y, n.x}; }
void require(bool b, const char* msg) { if (!b) throw std::runtime_error(msg); }
void near(double a, double b, double eps=1e-10) {
    require(std::isfinite(a) && std::isfinite(b) && std::abs(a-b)<=eps, "unexpected numeric result");
}
Vec2 unit(Vec2 n) {
    require(std::isfinite(n.x) && std::isfinite(n.y), "nonfinite normal");
    const double length=std::hypot(n.x,n.y);
    require(length>1e-12 && std::isfinite(length), "degenerate normal");
    return n*(1.0/length);
}
// Feature indices come from a *narrowphase* feature matcher. They are not array indices.
// Pair orientation is canonical; swapping bodies is not interchangeable with reusing this cache.
struct Key {
    std::uint64_t bodyA{},bodyB{},featureA{},featureB{};
    auto operator<=>(const Key&) const = default;
};
struct ContactInput {
    Key key{};
    Vec2 normal{0,1};
    double friction{}, timeStep{};
};
struct CachedImpulse {
    Vec2 normal{0,1};
    double normalMagnitude{}, tangentMagnitude{}, friction{},timeStep{};
    std::uint64_t lastSeenFrame{};
};
struct Seed { double normal{}, tangent{}; bool reused{}; };
class ContactCache {
    std::map<Key,CachedImpulse> entries_;
    std::uint64_t frame_{};
    static constexpr double minimumNormalCosine=0.9659258262890683; // 15 deg
    static constexpr double maxStepRatio=2.0;
    static void validate(const ContactInput& in) {
        require(in.key.bodyA<in.key.bodyB, "body pair must have canonical orientation");
        require(std::isfinite(in.friction) && in.friction>=0, "invalid friction");
        require(std::isfinite(in.timeStep) && in.timeStep>0, "invalid timestep");
        (void)unit(in.normal);
    }
public:
    void begin_frame(std::uint64_t id) {
        require(id>frame_, "frame ids must increase"); frame_=id;
    }
    Seed lookup(const ContactInput& in) const {
        require(frame_>0, "begin_frame required"); validate(in);
        const auto it=entries_.find(in.key);
        if(it==entries_.end()) return {};
        const auto& old=it->second;
        // Only the immediately previous frame may warm start. Missing a frame invalidates state.
        if(old.lastSeenFrame!=frame_-1) return {};
        const Vec2 previous=unit(old.normal),current=unit(in.normal);
        const double alignment=dot(previous,current);
        if(alignment<minimumNormalCosine) return {};
        const double ratio=in.timeStep/old.timeStep;
        if(!std::isfinite(ratio) || ratio<1/maxStepRatio || ratio>maxStepRatio) return {};
        // A material edit invalidates the tangential cache, not the physical normal reaction.
        // Project the previous world-space tangential impulse onto the current tangent.
        const Vec2 previousTangentImpulse=tangent(previous)*old.tangentMagnitude;
        const double normal=old.normalMagnitude*ratio;
        const double tangentValue=(old.friction==in.friction)
            ? dot(previousTangentImpulse,tangent(current))*ratio : 0;
        return {normal,std::clamp(tangentValue,-in.friction*normal,in.friction*normal),true};
    }
    void store(const ContactInput& in,double normalImpulse,double tangentImpulse) {
        require(frame_>0,"begin_frame required"); validate(in);
        require(std::isfinite(normalImpulse) && normalImpulse>=0,"invalid normal impulse");
        require(std::isfinite(tangentImpulse),"invalid tangent impulse");
        require(std::abs(tangentImpulse)<=in.friction*normalImpulse+1e-9,"friction cone exceeded");
        // A repeated write for the same feature in one frame indicates a duplicate manifold row.
        const auto it=entries_.find(in.key);
        require(it==entries_.end() || it->second.lastSeenFrame!=frame_,"duplicate feature key");
        entries_[in.key]={unit(in.normal),normalImpulse,tangentImpulse,in.friction,in.timeStep,frame_};
    }
    void prune() {
        for(auto it=entries_.begin();it!=entries_.end();) {
            if(it->second.lastSeenFrame!=frame_)it=entries_.erase(it); else ++it;
        }
    }
    std::size_t size() const { return entries_.size(); }
};
int main() {
    const Key id{4,9,2,7};
    ContactCache cache; ContactInput in{id,{0,1},0.5,1.0/60.0};
    cache.begin_frame(1);
    require(!cache.lookup(in).reused,"new feature had cache");
    cache.store(in,2,0.5);
    cache.begin_frame(2);
    auto seed=cache.lookup(in);
    require(seed.reused,"persistent identity not reused"); near(seed.normal,2);near(seed.tangent,0.5);
    // Rotating the tangent frame changes the scalar, but preserves the projection.
    const double a=10*3.14159265358979323846/180;
    ContactInput rotated=in;rotated.normal={-std::sin(a),std::cos(a)};
    seed=cache.lookup(rotated);require(seed.reused,"small normal drift invalidated");
    near(seed.tangent,0.5*std::cos(a));
    ContactInput sharp=in;sharp.normal={-0.5,std::sqrt(0.75)};
    require(!cache.lookup(sharp).reused,"large normal drift accepted");
    ContactInput swapped=in;swapped.key={9,4,7,2};
    bool rejected=false;try{(void)cache.lookup(swapped);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"reversed body order accepted");
    ContactInput changedFeature=in;changedFeature.key.featureB=8;
    require(!cache.lookup(changedFeature).reused,"different geometry feature reused");
    ContactInput halfStep=in;halfStep.timeStep*=0.5;
    seed=cache.lookup(halfStep);require(seed.reused,"bounded timestep change rejected");
    near(seed.normal,1);near(seed.tangent,0.25);
    ContactInput jumpStep=in;jumpStep.timeStep*=4;
    require(!cache.lookup(jumpStep).reused,"large timestep jump accepted");
    ContactInput changedFriction=in;changedFriction.friction=0.1;
    seed=cache.lookup(changedFriction);require(seed.reused,"material edit erased normal cache");
    near(seed.normal,2);near(seed.tangent,0);
    cache.store(in,1,0.25);
    rejected=false;try{cache.store(in,1,0.25);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"duplicate feature admitted");
    cache.prune();require(cache.size()==1,"prune failure");
    cache.begin_frame(4);require(!cache.lookup(in).reused,"skipped frame reused");
    cache.prune();require(cache.size()==0,"stale feature survived prune");
    ContactInput bad=in;bad.normal={0,0};
    rejected=false;try{(void)cache.lookup(bad);}catch(const std::runtime_error&){rejected=true;}
    require(rejected,"degenerate normal accepted");
    std::cout<<"contact cache: identity, tangent transport, timestep, invalidation PASS\n";
}

// C++20 analytic linear-motion CCD for two disks, not a general rigid-body CCD system.
// Build: c++ -std=c++20 -O2 -Wall -Wextra -Wpedantic -Werror disk_ccd_lab.cpp -o /tmp/disk_ccd && /tmp/disk_ccd
#include <algorithm>
#include <cmath>
#include <iostream>
#include <limits>
#include <optional>
#include <stdexcept>
struct Vec2 { double x{},y{}; };
constexpr Vec2 operator+(Vec2 a,Vec2 b){return {a.x+b.x,a.y+b.y};}
constexpr Vec2 operator-(Vec2 a,Vec2 b){return {a.x-b.x,a.y-b.y};}
constexpr Vec2 operator*(Vec2 a,double t){return {a.x*t,a.y*t};}
constexpr double dot(Vec2 a,Vec2 b){return a.x*b.x+a.y*b.y;}
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
void near(double a,double b,double eps=1e-10){check(std::isfinite(a)&&std::abs(a-b)<eps,"numeric result mismatch");}
struct Disk{Vec2 center{},velocity{};double radius{};};
struct Hit{double time{};Vec2 normal{};bool initiallyOverlapping{};};
void validate(const Disk& d){
 check(std::isfinite(d.center.x)&&std::isfinite(d.center.y)&&
       std::isfinite(d.velocity.x)&&std::isfinite(d.velocity.y)&&
       std::isfinite(d.radius)&&d.radius>=0,"invalid disk");
}
// Relative separation p(t) = p0 + t*v, with disk radius sum R.
// Solve |p(t)|^2 = R^2, or a*t^2 + b*t + c = 0.
std::optional<Hit> first_disk_contact(const Disk& A,const Disk& B,double dt){
 validate(A);validate(B);
 check(std::isfinite(dt)&&dt>=0,"invalid frame duration");
 const Vec2 p=B.center-A.center, v=B.velocity-A.velocity;
 const double R=A.radius+B.radius;
 const double a=dot(v,v), b=2*dot(p,v), c=dot(p,p)-R*R;
 check(std::isfinite(R)&&std::isfinite(a)&&std::isfinite(b)&&std::isfinite(c),
       "out-of-range relative geometry");
 auto normalAt=[&](double t){
   const Vec2 sep=p+v*t;
   const double d=std::hypot(sep.x,sep.y);
   if(d>0)return sep*(1.0/d);
   const double speed=std::hypot(v.x,v.y);
   // Deterministic fallback for coincident centres; no unique geometric normal exists.
   return speed>0?v*(-1.0/speed):Vec2{1,0};
 };
 if(c<=0)return Hit{0,normalAt(0),c<0}; // existing overlap handled by another stage
 if(a==0 || b>=0)return std::nullopt; // no relative motion or not closing
 // fma avoids one rounding in the discriminant when supported by the platform.
 const double discriminant=std::fma(b,b,-4*a*c);
 if(!(discriminant>=0))return std::nullopt; // includes NaN rejection
 const double root=std::sqrt(discriminant);
 // Numerically stable quadratic roots. Here b<0, so q is nonzero and positive.
 const double q=-0.5*(b- root);
 if(!(q>0))return std::nullopt;
 const double nearRoot=c/q;
 const double farRoot=q/a;
 const double t=std::min(nearRoot,farRoot);
 if(!(std::isfinite(t)&&t>=0&&t<=dt))return std::nullopt;
 return Hit{t,normalAt(t),false};
}
int main(){
 const Disk still{{0,0},{0,0},1},bullet{{10,0},{-100,0},1};
 auto h=first_disk_contact(still,bullet,0.1);
 check(h.has_value(),"tunneling hit missed");near(h->time,0.08);near(h->normal.x,1);
 check(!first_disk_contact(still,bullet,0.05),"hit beyond frame accepted");
 check(!first_disk_contact(still,Disk{{10,0},{100,0},1},1),"separating disk hit");
 check(!first_disk_contact(still,Disk{{10,2.1},{-100,0},1},1),"near miss hit");
 h=first_disk_contact(still,Disk{{10,2},{-10,0},1},2);
 check(h.has_value(),"grazing hit missed");near(h->time,1);near(h->normal.y,1);
 h=first_disk_contact(still,Disk{{1,0},{0,0},1},1);
 check(h.has_value()&&h->initiallyOverlapping,"overlap policy broken");near(h->time,0);
 h=first_disk_contact(still,Disk{{0,0},{0,0},1},0);
 check(h.has_value(),"coincident overlap missed");near(h->normal.x,1);
 // Relative motion is invariant under a common uniform Galilean velocity.
 h=first_disk_contact(Disk{{0,0},{55,7},1},Disk{{10,0},{-45,7},1},0.1);
 check(h.has_value(),"relative velocity test failed");near(h->time,0.08);
 // Large coordinate and velocity magnitudes exercise the stable-root path.
 h=first_disk_contact(Disk{{0,0},{0,0},1},Disk{{1000000,0},{-1000000,0},1},2);
 check(h.has_value(),"large-scale impact missed");near(h->time,0.999998,1e-8);
 bool rejected=false;
 try{(void)first_disk_contact(still,bullet,-1);}catch(const std::runtime_error&){rejected=true;}
 check(rejected,"negative timestep accepted");
 rejected=false;
 try{(void)first_disk_contact(still,Disk{{10,0},{-1,0},-1},1);}catch(const std::runtime_error&){rejected=true;}
 check(rejected,"negative radius accepted");
 std::cout<<"disk CCD: tunneling, grazing, overlap, misses, invariance, validation PASS\n";
}

